# Create output where only "down-pointing" T shapes are flipped to point up
from collections import deque

def flatten_components(components):
    result = set()
    for comp in components:
        for c in comp:
            result.add(c)
    return result

def point_up(comp):
    """Flip a component vertically (swap top and bottom)"""
    rows = min(r for r,c in comp)
    max_rows = max(r for r,c in comp)
    new_comp = []
    for r, c in comp:
        new_r = max_rows - (r - rows)
        new_comp.append((new_r, c))
    return new_comp

def point_down(comp):
    """Flip a component vertically"""
    rows = min(r for r,c in comp)
    max_rows = max(r for r,c in comp)
    new_comp = []
    for r, c in comp:
        new_r = max_rows - (r - rows)
        new_comp.append((new_r, c))
    return new_comp

components = [[(1, 2), (2, 1), (2, 2), (2, 3)], [(2, 7), (2, 8), (2, 9), (3, 8)], [(4, 2), (4, 3), (4, 4), (5, 3)], [(6, 6), (6, 7), (6, 8), (7, 7)], [(7, 2), (8, 1), (8, 2), (8, 3)]]

# Identify which components point up (single row above the 3-center row)
def get_shape_signature(comp):
    rows = sorted([r for r,c in comp])
    col_counts = {}
    for r,c in comp:
        col_counts[r] = col_counts.get(r, 0) + 1
    most_common_row = max(col_counts.keys(), key=lambda k: col_counts[k])
    # 3 cells on most_common_row = points down (need to flip to up)
    # 1 cell on most_common_row = originally pointed up (or is L)
    if col_counts[most_common_row] == 3:
        return 'DOWN'  # Has T-shape pointing down, should flip to point up (away from base)
    return 'UP'  # Usually already pointed up

for i, comp in enumerate(components):
    sig = get_shape_signature(comp)
    print(f"Component {i+1}: shape={sig}, cells={comp}")

# Now create output grid
output = [[0 for _ in range(11)] for _ in range(10)]
for i, comp in enumerate(components):
    rows = sorted([r for r,c in comp])
    sig = get_shape_signature(comp)

    if sig == 'DOWN':
        # Flip to point up (swap rows)
        new_comp = []
        for r, c in comp:
            new_r = max(rows) - (r - min(rows))
            new_comp.append((new_r, c))
        output_comp = sorted(new_comp)
    else:
        # Keep as is
        output_comp = sorted(comp)

    for r, c in output_comp:
        output[r][c] = 2

print("\nOutput grid:")
for row in output:
    print(" ".join(str(x) for x in row))

